import sys
from io import StringIO
import unittest


def resolve():
    N, A, B = [int(i) for i in input().split()]
    if abs(A - B) % 2 == 0:
        print(int(abs(A - B) / 2))
    # A->1 or B->N
    elif A - 1 < N - B:
        # A->1
        if B - (A - 1) == 2:
            print(A - 1 + 1)
        elif (B - (A - 1) - 1) % 2 == 0:
            print(int(A - 1 + ((B - (A - 1) - 1) / 2)))
        else:
            print(int(A - 2 + ((B - (A - 2) - 1) / 2)))
    else:
        if A + (N - B) == N - 1:
            print(N - B + 1)
        elif (N - A + (N - B)) % 2 == 0:
            print(int(N - B + ((N - A + (N - B)) / 2)))
        else:
            print(int(N - B + 1 + ((N - A + (N - B + 1)) / 2)))
    return


