def min_steps_v2(n, a, b):
    if (b - a) % 2 == 0:
        return int((b - a) / 2)

    # odd case
    a_diff = a - 1
    b_diff = n - b

    if a_diff > b_diff:
      steps_to_even = n - b + 1
      remain_steps = min_steps_v2(n, a + (n - b) + 1, n)
    else:
      steps_to_even = a
      remain_steps = min_steps_v2(n, 1, b - a)

    return steps_to_even + remain_steps

